cy.get('.left-secondary-menu .left-menu-items.main-menu li>sa-menu-item>a').contains('span', 'Shareholders/Partners').click();
//get current count of shareholders
var totalStakeholdersCount;
cy.request({
    method: 'GET',
    url: "https://complytek-testing-api.regtek.co/api/paging/".concat(clientId, "/shareholders?skip=0&requireTotalCount=true"),
    headers: {
        "Content-Type": "application/json",
        'Authorization': "Bearer ".concat(token)
    }
}).then(function (res) {
    totalStakeholdersCount = res.body.totalCount;
});
cy.request({
    method: 'POST',
    url: "https://complytek-testing-api.regtek.co/api/clientCorporates/".concat(clientId, "/shareholders"),
    headers: {
        "Content-Type": "application/json",
        'Authorization': "Bearer ".concat(token)
    },
    body: {
        "clientId": clientId,
        "shareholderCapacity": 2,
        "includeInEvaluation": true,
        "isControllingPerson": false,
        "isNominee": false,
        "appointmentDate": "2024-10-31",
        "resignationDate": "2024-11-01",
        "isLegalRepresentative": false,
        "profileId": clientId,
        "rateWeightPercentage": 65,
        "numberOfShares": null,
        "clientType": "1",
        "externalReference": null,
        "ignoreAutoOngoingMonitoringStatus": false,
        "clientCorporate": {
            "appointmentDate": "2024-10-31",
            "resignationDate": "2024-11-01"
        },
        "customFields": {}
    }
}).then(function (res) {
    // get current count of shareholders
    //expecting the count to be plus 1
    cy.request({
        method: 'GET',
        url: "https://complytek-testing-api.regtek.co/api/paging/".concat(clientId, "/shareholders?skip=0&requireTotalCount=true"),
        headers: {
            "Content-Type": "application/json",
            'Authorization': "Bearer ".concat(token)
        }
    }).then(function (res) {
        var updatedTotalStakeholderCount = res.body.totalCount;
        expect(updatedTotalStakeholderCount).to.equal(totalStakeholdersCount + 1);
    });
});

